-- Motorcycle Comparison API - Harley-Davidson technical specifications
-- Generated from zontes-scraper/harley_davidson_motos.json (scraped 2026-08-28T10:58:03+00:00) by
-- tools/import-harley-davidson-specs.mjs.
--
-- Sources, as recorded by the scraper:
--   site_oficial: https://www.harley-davidson.com/br/pt/motorcycles/
--   motorcyclespecs: https://www.motorcyclespecs.co.za/bikes/H-D.htm
--   motorcyclist: https://motorcyclist.com.br/ficha/harley-davidson
--   fipe: https://parallelum.com.br/fipe/api/v1/motos/marcas/77/modelos
--
-- The JSON "id" is the same base slug the FIPE seed derives, so rows join on motorcycles.slug rather
-- than on any fuzzy name match. All 200 scraped model-years already exist in the catalogue
-- (199 from the FIPE snapshot, 1 - the Sportster S - from R__dev_seed.sql), so against today's seeds
-- this import creates no motorcycles and only fills gaps. 199 of them carry something usable and
-- are emitted; the one that does not is listed at the foot of this header, and it is the
-- row the scraper matched to no source sheet at all.
-- The insert path below still runs: whether a row is new is derived from the database at run
-- time rather than from a flag baked in here, so a slug the catalogue does not have is created rather
-- than dropped.
--
-- Nothing is estimated. A value absent from the source stays NULL, and every figure below was parsed
-- from the source string: hp from hp/bhp/cv/PS/kW, Nm from Nm/kgf.m/lb-ft, and litres from the litre
-- form only (the sheets print "18.5 Litres / 4.9 US gal", and the gallon figure must never win). The
-- sources disagree on decimal convention inside the same file ("11,7 l" beside "18.5 Litres"), so a
-- separator is read from its own shape: exactly three trailing digits is a thousands group, anything
-- else is a decimal point. These are American sheets, so a measurement is read in mm wherever mm was
-- printed and converted from inches only where it was not - 15 values came in that way.
--
-- Seat height needs saying explicitly. Harley publishes two figures on one line - "Laden2 693.4 mm /
-- 27.3 in Unladen 779.8 mm / 30.7 in", where the trailing 2 is a footnote marker - and 51 of the rows
-- here are written that way. seat_height_mm stores the UNLADEN figure. Every other brand in this
-- catalogue publishes a single seat height and it is the unladen one, so storing the laden figure
-- would make these bikes read 40-60 mm lower than their rivals in the comparison this table exists
-- for. The laden figure is not thrown away: it goes to the long tail as 'Altura do Assento (com
-- piloto)', where it cannot be mistaken for the other one.
--
-- One source figure is not taken on trust: the cylinder count. Bore, stroke and displacement are
-- printed on the same sheet, so their product decides the count whenever the prose beside them
-- disagrees. Here it never does (0 corrections) - every engine in the snapshot is a V-twin and the
-- sheets say so - but the check is kept, because a future re-scrape that mislabels a sheet should be
-- caught rather than stored. "45° V-Twin" and "Twin Cam 88" are both read as two cylinders; the 2 in
-- "2 valves per cylinder" is not read as a count.
--
-- One encoding fault is repaired on the way in (97 values): the micron sign in the oil-filter rating
-- was decoded as an i-grave, so the lubrication text reads "spin on 10ì pressurized oil filter" where
-- the sheet reads "10µ". That is extraction damage, not source content. A second fault is left alone:
-- the extractor also spaces digits out, and a number it has broken up is refused rather than read as
-- its first fragment, because a plausibility bound cannot catch a wrong figure that lands inside the
-- range. 13 numeric reads were refused on that rule. The spaced digits this snapshot actually carries
-- are all in tyre designations ("D401 160/70B17 73V"), which are stored as text and never parsed for
-- a figure, and in the seat-height footnote marker, which has its own parser.
--
-- Implausible figures are dropped rather than stored, each against the range its column can sensibly
-- hold:
--   none
-- 219 values exceeded their column width and were cut at a word boundary rather than mid-word.
--
-- Caveat worth knowing before trusting any single row. Only the Sportster S is still in production, so
-- the official Harley-Davidson sheet and motorcyclist.com.br reach exactly one of these 200 rows; the
-- other 199 lean entirely on motorcyclespecs.co.za, which publishes the global sheet rather than the
-- Brazilian one and reuses a single sheet across a whole generation. Figures are representative of the
-- generation, not specific to the year on the row. The scraper also grades its own matches, and not
-- all 200 are exact: 162 matched a sheet outright, 20 matched the base model, 12 matched a
-- neighbouring generation, 5 matched a neighbouring generation of the base model, and 1 matched
-- nothing at all. The last two grades are the ones to distrust on a spec-by-spec basis. Matching is
-- filtered on the factory code rather than the name, which is what keeps the Fat Boy (FLSTF) apart
-- from the Fat Bob (FXDF) and the Electra Glide Classic (FLHTC) apart from the Ultra Classic (FLHTCU).
--
-- Images. The scraper stores its gallery under img/harley-davidson/<generation>/, which is per
-- generation, not per model-year, so the 73 distinct photos below cover all 199 rows. Each row
-- still gets its own stored copy under a name derived from its slug (UUID v5, matching the shape
-- FileStorageServiceImpl will read): MotorcycleService treats the file as owned by the row and deletes
-- it when the motorcycle or its image is deleted, so a shared file name would blank every other row
-- pointing at it.
-- The files themselves are NOT in the repository - uploads/ is gitignored. Run
-- `node tools/import-harley-davidson-specs.mjs` to materialise them from a zontes-scraper checkout;
-- until then these rows serve a 404 for their image.
--
-- Existing rows are only ever gap-filled: every write is COALESCE(existing, imported), so an admin
-- edit, an uploaded image or a richer earlier import is never overwritten. That matters for exactly
-- one row here - the hand-curated Sportster S in R__dev_seed.sql - because the other 198 arrived from
-- FIPE with every specification column NULL, so for them a gap-fill is a full population. Long-tail
-- specs use ON CONFLICT DO NOTHING, which leaves the FIPE seed's own 'Fuel' and 'Reference price
-- (BRL)' intact, and reuse the key names the Honda, Yamaha and Royal Enfield imports chose so a
-- cross-brand comparison lines its rows up. Category is deliberately not touched: the catalogue enum
-- has no Cruiser sub-segment for the one row that names "Sport Cruiser", and overwriting on a lossy
-- mapping would degrade the segment filter rather than improve it. Repeatable and idempotent:
-- re-running changes nothing once it has been applied.
--
-- Populated column counts across the 199 imported rows:
--   engine: displacement_cc 199, max_power_hp 178, max_torque_nm 199, gears 199, cylinders 199
--   frame:  frame_type 142, front_suspension 199, front_tyre 199, abs_type 1
--   dims:   kerb_weight_kg 97, dry_weight_kg 188, seat_height_mm 170, fuel_capacity_l 186 (199 rows get a dimension block)
--   image_url 199; long-tail spec rows: 1190
-- Rows carrying nothing usable and therefore not emitted: harley-davidson-softail-custom-1995

BEGIN;

CREATE TEMP TABLE tmp_harley_spec_import (
    row_no                   bigint PRIMARY KEY,
    slug                     varchar(160) NOT NULL,
    is_new                   boolean NOT NULL,
    brand                    varchar(60),
    model                    varchar(120),
    model_year               integer,
    category                 varchar(20),
    image_url                varchar(512),
    frame_type               varchar(120),
    front_suspension         varchar(160),
    rear_suspension          varchar(160),
    front_brake              varchar(160),
    rear_brake               varchar(160),
    abs_type                 varchar(80),
    front_tyre               varchar(60),
    rear_tyre                varchar(60),
    engine_type              varchar(80),
    displacement_cc          integer,
    cylinders                integer,
    valves_per_cylinder      integer,
    max_power_hp             numeric(6,1),
    max_power_rpm            integer,
    max_torque_nm            numeric(6,1),
    max_torque_rpm           integer,
    compression_ratio        varchar(20),
    bore_mm                  numeric(6,2),
    stroke_mm                numeric(6,2),
    cooling_system           varchar(40),
    fuel_system              varchar(120),
    transmission_type        varchar(60),
    gears                    integer,
    final_drive              varchar(40),
    top_speed_kph            integer,
    fuel_consumption_l_100km numeric(5,2),
    emission_standard        varchar(30),
    length_mm                integer,
    width_mm                 integer,
    height_mm                integer,
    wheelbase_mm             integer,
    seat_height_mm           integer,
    ground_clearance_mm      integer,
    kerb_weight_kg           numeric(6,1),
    dry_weight_kg            numeric(6,1),
    fuel_capacity_l          numeric(5,1),
    motorcycle_id            bigint,
    engine_id                bigint,
    dimension_id             bigint
) ON COMMIT DROP;

CREATE TEMP TABLE tmp_harley_spec_kv (
    row_no     bigint NOT NULL,
    spec_key   varchar(80) NOT NULL,
    spec_value varchar(500),
    PRIMARY KEY (row_no, spec_key)
) ON COMMIT DROP;





-- Bind every imported row to its catalogue row. The FIPE seed derives the same slug from the same
-- FIPE model descriptor, so this is an equality join and not a fuzzy match.
UPDATE tmp_harley_spec_import s
SET motorcycle_id = m.id,
    engine_id     = m.engine_specification_id,
    dimension_id  = m.dimension_id
FROM motorcycles m
WHERE m.slug = s.slug;

-- What counts as new is decided here, from the database, not from the flag carried in the VALUES
-- above. That flag records what was true when this file was generated; the catalogue may since have
-- gained or lost the model. Deriving it means an existing model is never inserted twice, and a model
-- the catalogue does not have is created rather than quietly dropped.
UPDATE tmp_harley_spec_import SET is_new = (motorcycle_id IS NULL);

DO $$
BEGIN
    IF pg_get_serial_sequence('engine_specifications', 'id') IS NULL
       OR pg_get_serial_sequence('dimensions', 'id') IS NULL
       OR pg_get_serial_sequence('motorcycles', 'id') IS NULL THEN
        RAISE EXCEPTION 'A target table has no serial/identity sequence';
    END IF;
END $$;

-- ---------------------------------------------------------------------------
-- New models: allocate ids, then build engine, dimension and catalogue rows.
-- ---------------------------------------------------------------------------
UPDATE tmp_harley_spec_import
SET motorcycle_id = nextval(pg_get_serial_sequence('motorcycles', 'id')::regclass),
    engine_id     = nextval(pg_get_serial_sequence('engine_specifications', 'id')::regclass)
WHERE is_new;

-- A dimension row is created only where the source published a measurement; an empty placeholder
-- would add a row that exists only to render dashes in the comparison table.
UPDATE tmp_harley_spec_import
SET dimension_id = nextval(pg_get_serial_sequence('dimensions', 'id')::regclass)
WHERE is_new
  AND num_nonnulls(length_mm, width_mm, height_mm, wheelbase_mm, seat_height_mm,
                   ground_clearance_mm, kerb_weight_kg, dry_weight_kg, fuel_capacity_l) > 0;

    id, engine_type, displacement_cc, cylinders, valves_per_cylinder, max_power_hp, max_power_rpm,
    max_torque_nm, max_torque_rpm, compression_ratio, bore_mm, stroke_mm, cooling_system, fuel_system,
    transmission_type, gears, final_drive, top_speed_kph, fuel_consumption_l_100km, emission_standard
)
SELECT engine_id, engine_type, displacement_cc, cylinders, valves_per_cylinder, max_power_hp, max_power_rpm,
       max_torque_nm, max_torque_rpm, compression_ratio, bore_mm, stroke_mm, cooling_system, fuel_system,
       transmission_type, gears, final_drive, top_speed_kph, fuel_consumption_l_100km, emission_standard
FROM tmp_harley_spec_import
WHERE is_new
ORDER BY row_no;

    id, length_mm, width_mm, height_mm, wheelbase_mm, seat_height_mm, ground_clearance_mm,
    kerb_weight_kg, dry_weight_kg, fuel_capacity_l
)
SELECT dimension_id, length_mm, width_mm, height_mm, wheelbase_mm, seat_height_mm, ground_clearance_mm,
       kerb_weight_kg, dry_weight_kg, fuel_capacity_l
FROM tmp_harley_spec_import
WHERE is_new AND dimension_id IS NOT NULL
ORDER BY row_no;

-- price_eur stays NULL: a model outside the FIPE snapshot has no reference price here, and a guessed
-- one would be indistinguishable from a real one once it is in the catalogue.
    id, slug, version, brand, model, model_year, category, price_eur, image_url, description,
    frame_type, front_suspension, rear_suspension, front_brake, rear_brake, abs_type,
    front_tyre, rear_tyre, engine_specification_id, dimension_id, created_at, updated_at
)
SELECT motorcycle_id, slug, 0, brand, model, model_year, category, NULL, image_url, NULL,
       frame_type, front_suspension, rear_suspension, front_brake, rear_brake, abs_type,
       front_tyre, rear_tyre, engine_id, dimension_id, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM tmp_harley_spec_import
WHERE is_new
ORDER BY row_no;

-- ---------------------------------------------------------------------------
-- Existing models: gap-fill only.
-- ---------------------------------------------------------------------------

-- The FIPE seed created an engine block for every row it inserted, but an earlier import may not
-- have. Give those an engine row first, so their figures are not silently dropped below.
UPDATE tmp_harley_spec_import
SET engine_id = nextval(pg_get_serial_sequence('engine_specifications', 'id')::regclass)
WHERE NOT is_new AND engine_id IS NULL;

SELECT s.engine_id
FROM tmp_harley_spec_import s
WHERE NOT s.is_new
  AND s.engine_id IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM engine_specifications e WHERE e.id = s.engine_id)
ORDER BY s.row_no;

UPDATE motorcycles m
SET engine_specification_id = s.engine_id
FROM tmp_harley_spec_import s
WHERE m.id = s.motorcycle_id AND NOT s.is_new AND m.engine_specification_id IS NULL;

UPDATE engine_specifications e
SET engine_type              = COALESCE(e.engine_type, s.engine_type),
    displacement_cc          = COALESCE(e.displacement_cc, s.displacement_cc),
    cylinders                = COALESCE(e.cylinders, s.cylinders),
    valves_per_cylinder      = COALESCE(e.valves_per_cylinder, s.valves_per_cylinder),
    max_power_hp             = COALESCE(e.max_power_hp, s.max_power_hp),
    max_power_rpm            = COALESCE(e.max_power_rpm, s.max_power_rpm),
    max_torque_nm            = COALESCE(e.max_torque_nm, s.max_torque_nm),
    max_torque_rpm           = COALESCE(e.max_torque_rpm, s.max_torque_rpm),
    compression_ratio        = COALESCE(e.compression_ratio, s.compression_ratio),
    bore_mm                  = COALESCE(e.bore_mm, s.bore_mm),
    stroke_mm                = COALESCE(e.stroke_mm, s.stroke_mm),
    cooling_system           = COALESCE(e.cooling_system, s.cooling_system),
    fuel_system              = COALESCE(e.fuel_system, s.fuel_system),
    transmission_type        = COALESCE(e.transmission_type, s.transmission_type),
    gears                    = COALESCE(e.gears, s.gears),
    final_drive              = COALESCE(e.final_drive, s.final_drive),
    top_speed_kph            = COALESCE(e.top_speed_kph, s.top_speed_kph),
    fuel_consumption_l_100km = COALESCE(e.fuel_consumption_l_100km, s.fuel_consumption_l_100km),
    emission_standard        = COALESCE(e.emission_standard, s.emission_standard)
FROM tmp_harley_spec_import s
WHERE e.id = s.engine_id AND NOT s.is_new;

-- A row seeded from FIPE carries no dimension block at all, so allocate one wherever this import
-- has something to put in it.
UPDATE tmp_harley_spec_import
SET dimension_id = nextval(pg_get_serial_sequence('dimensions', 'id')::regclass)
WHERE NOT is_new
  AND dimension_id IS NULL
  AND num_nonnulls(length_mm, width_mm, height_mm, wheelbase_mm, seat_height_mm,
                   ground_clearance_mm, kerb_weight_kg, dry_weight_kg, fuel_capacity_l) > 0;

    id, length_mm, width_mm, height_mm, wheelbase_mm, seat_height_mm, ground_clearance_mm,
    kerb_weight_kg, dry_weight_kg, fuel_capacity_l
)
SELECT s.dimension_id, s.length_mm, s.width_mm, s.height_mm, s.wheelbase_mm, s.seat_height_mm,
       s.ground_clearance_mm, s.kerb_weight_kg, s.dry_weight_kg, s.fuel_capacity_l
FROM tmp_harley_spec_import s
WHERE NOT s.is_new
  AND s.dimension_id IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM dimensions d WHERE d.id = s.dimension_id)
ORDER BY s.row_no;

-- Where a dimension block already existed, gap-fill it the same way as the engine block.
UPDATE dimensions d
SET length_mm           = COALESCE(d.length_mm, s.length_mm),
    width_mm            = COALESCE(d.width_mm, s.width_mm),
    height_mm           = COALESCE(d.height_mm, s.height_mm),
    wheelbase_mm        = COALESCE(d.wheelbase_mm, s.wheelbase_mm),
    seat_height_mm      = COALESCE(d.seat_height_mm, s.seat_height_mm),
    ground_clearance_mm = COALESCE(d.ground_clearance_mm, s.ground_clearance_mm),
    kerb_weight_kg      = COALESCE(d.kerb_weight_kg, s.kerb_weight_kg),
    dry_weight_kg       = COALESCE(d.dry_weight_kg, s.dry_weight_kg),
    fuel_capacity_l     = COALESCE(d.fuel_capacity_l, s.fuel_capacity_l)
FROM tmp_harley_spec_import s
WHERE d.id = s.dimension_id AND NOT s.is_new;

-- A gap-fill that would push dry weight above a kerb weight already on the row is dropped: the
-- CHECK would otherwise abort the entire import over one bad source figure.
UPDATE dimensions
SET dry_weight_kg = NULL
WHERE dry_weight_kg IS NOT NULL
  AND kerb_weight_kg IS NOT NULL
  AND dry_weight_kg > kerb_weight_kg;

-- image_url is gap-filled like everything else, so an image an admin uploaded through
-- POST /api/v1/motorcycles/{id}/image always wins over the scraped one. It is never cleared here:
-- removeImage deletes the file behind a URL this API issued, and this import must not orphan one.
UPDATE motorcycles m
SET frame_type       = COALESCE(m.frame_type, s.frame_type),
    front_suspension = COALESCE(m.front_suspension, s.front_suspension),
    rear_suspension  = COALESCE(m.rear_suspension, s.rear_suspension),
    front_brake      = COALESCE(m.front_brake, s.front_brake),
    rear_brake       = COALESCE(m.rear_brake, s.rear_brake),
    abs_type         = COALESCE(m.abs_type, s.abs_type),
    front_tyre       = COALESCE(m.front_tyre, s.front_tyre),
    rear_tyre        = COALESCE(m.rear_tyre, s.rear_tyre),
    image_url        = COALESCE(m.image_url, s.image_url),
    dimension_id     = COALESCE(m.dimension_id, s.dimension_id),
    -- @Version belongs to Hibernate; bump it here because this writes behind the ORM's back, so a
    -- session holding a stale copy of one of these rows fails its next flush instead of quietly
    -- overwriting the import.
    version          = m.version + 1,
    updated_at       = CURRENT_TIMESTAMP
FROM tmp_harley_spec_import s
WHERE m.id = s.motorcycle_id
  AND NOT s.is_new
  -- Each arm is "the row lacks it AND the import supplies it", so a row this file has nothing left
  -- to add is not touched at all. Testing only for NULL would bump version and updated_at on every
  -- re-run for any column the source never published.
  AND ((m.frame_type IS NULL AND s.frame_type IS NOT NULL)
       OR (m.front_suspension IS NULL AND s.front_suspension IS NOT NULL)
       OR (m.rear_suspension IS NULL AND s.rear_suspension IS NOT NULL)
       OR (m.front_brake IS NULL AND s.front_brake IS NOT NULL)
       OR (m.rear_brake IS NULL AND s.rear_brake IS NOT NULL)
       OR (m.abs_type IS NULL AND s.abs_type IS NOT NULL)
       OR (m.front_tyre IS NULL AND s.front_tyre IS NOT NULL)
       OR (m.rear_tyre IS NULL AND s.rear_tyre IS NOT NULL)
       OR (m.image_url IS NULL AND s.image_url IS NOT NULL)
       OR (m.dimension_id IS NULL AND s.dimension_id IS NOT NULL));

-- ---------------------------------------------------------------------------
-- Long-tail specs. DO NOTHING preserves whatever is already stored under the same key,
-- including the FIPE seed's own 'Fuel' and 'Reference price (BRL)'.
-- ---------------------------------------------------------------------------
SELECT s.motorcycle_id, k.spec_key, k.spec_value
FROM tmp_harley_spec_kv k
JOIN tmp_harley_spec_import s ON s.row_no = k.row_no
WHERE s.motorcycle_id IS NOT NULL
  AND k.spec_value IS NOT NULL
  AND btrim(k.spec_value) <> ''
ON CONFLICT (motorcycle_id, spec_key) DO NOTHING;

-- ---------------------------------------------------------------------------
-- Defensive checks before commit.
-- ---------------------------------------------------------------------------
DO $$
DECLARE
    bad bigint;
BEGIN
    SELECT count(*) INTO bad
    FROM tmp_harley_spec_import s
    LEFT JOIN motorcycles m ON m.id = s.motorcycle_id
    WHERE m.id IS NULL;
    IF bad <> 0 THEN
        RAISE EXCEPTION 'Harley-Davidson spec import: % rows did not resolve to a catalogue row', bad;
    END IF;

    SELECT count(*) INTO bad
    FROM tmp_harley_spec_import s
    JOIN motorcycles m ON m.id = s.motorcycle_id
    WHERE s.engine_id IS NOT NULL AND m.engine_specification_id IS DISTINCT FROM s.engine_id;
    IF bad <> 0 THEN
        RAISE EXCEPTION 'Harley-Davidson spec import: % rows have a mismatched engine block', bad;
    END IF;

    SELECT count(*) INTO bad
    FROM dimensions
    WHERE dry_weight_kg IS NOT NULL AND kerb_weight_kg IS NOT NULL AND dry_weight_kg > kerb_weight_kg;
    IF bad <> 0 THEN
        RAISE EXCEPTION 'Harley-Davidson spec import: % dimension rows have dry weight above kerb weight', bad;
    END IF;

    -- lower(brand) rather than brand: V4 normalised casing before either seed had inserted a row, so
    -- an equality test here would silently depend on which seed wrote the row.
    SELECT count(*) INTO bad
    FROM motorcycles
    WHERE lower(brand) = 'harley-davidson' AND slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$';
    IF bad <> 0 THEN
        RAISE EXCEPTION 'Harley-Davidson spec import: % rows have a slug the public routing cannot use', bad;
    END IF;

    -- Every stored image URL has to be a name ImageController can actually serve: FileStorageServiceImpl
    -- reads UUID + jpg/png/webp and nothing else, so a name outside that shape is a silent 404.
    SELECT count(*) INTO bad
    FROM tmp_harley_spec_import
    WHERE image_url IS NOT NULL
      AND image_url !~ '^/api/v1/images/motorcycles/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(jpg|png|webp)$';
    IF bad <> 0 THEN
        RAISE EXCEPTION 'Harley-Davidson spec import: % image URLs are not a name the image endpoint can serve', bad;
    END IF;
END $$;

COMMIT;
